"use strict";(globalThis.webpackChunkhumanoid_robotics_textbook=globalThis.webpackChunkhumanoid_robotics_textbook||[]).push([[9575],{9881:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/introduction","label":"Introduction to Physical AI & Robotics","docId":"introduction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/setup-guide","label":"Development Environment Setup","docId":"setup-guide","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/hardware-requirements","label":"Hardware & Software Requirements","docId":"hardware-requirements","unlisted":false},{"type":"category","label":"Module 1: The Robotic Nervous System (ROS 2)","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-ros2/introduction","label":"Introduction to ROS 2","docId":"module-ros2/introduction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-ros2/labs","label":"ROS 2 Hands-on Lab: Publisher & Subscriber","docId":"module-ros2/labs","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-ros2/urdf-fundamentals","label":"Understanding URDF (Unified Robot Description Format)","docId":"module-ros2/urdf-fundamentals","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-ros2/quiz","label":"Module 1 Checkpoint Quiz: ROS 2 Fundamentals","docId":"module-ros2/quiz","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-ros2/troubleshooting","label":"Troubleshooting Common ROS 2 Issues (Module 1)","docId":"module-ros2/troubleshooting","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-ros2/advanced-topics","label":"Optional Advanced Topics: ROS 2","docId":"module-ros2/advanced-topics","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/Physical-AI-Humanoid-Robotics/docs/category/module-1-ros2"},{"type":"category","label":"Module 2: The Digital Twin (Gazebo & Unity)","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/introduction","label":"Introduction to Digital Twins and Simulation","docId":"module-digital-twin/introduction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/labs","label":"Digital Twin Lab: Importing URDF into Gazebo","docId":"module-digital-twin/labs","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/sensor-lab","label":"Digital Twin Lab: Adding Sensors in Gazebo","docId":"module-digital-twin/sensor-lab","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/code-examples","label":"Digital Twin Lab: Code Examples (Gazebo & Sensors)","docId":"module-digital-twin/code-examples","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/quiz","label":"Module 2 Checkpoint Quiz: Digital Twin and Simulation","docId":"module-digital-twin/quiz","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/troubleshooting","label":"Troubleshooting Common Simulation Issues (Module 2)","docId":"module-digital-twin/troubleshooting","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-digital-twin/advanced-topics","label":"Optional Advanced Topics: Digital Twin and Simulation","docId":"module-digital-twin/advanced-topics","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/Physical-AI-Humanoid-Robotics/docs/category/module-2-digital-twin"},{"type":"category","label":"Module 3: The AI-Robot Brain (NVIDIA Isaac)","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/introduction","label":"Introduction to AI-Robot Brain: NVIDIA Isaac","docId":"module-isaac-sim/introduction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/labs","label":"NVIDIA Isaac Lab: Setting Up Isaac Sim with a Robot","docId":"module-isaac-sim/labs","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/vslam-lab","label":"NVIDIA Isaac Lab: Visual SLAM (VSLAM)","docId":"module-isaac-sim/vslam-lab","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/bipedal-nav2-lab","label":"NVIDIA Isaac Lab: Bipedal Path Planning (Nav2)","docId":"module-isaac-sim/bipedal-nav2-lab","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/code-examples","label":"NVIDIA Isaac Lab: Code Examples (VSLAM & Nav2)","docId":"module-isaac-sim/code-examples","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/quiz","label":"Module 3 Checkpoint Quiz: AI-Robot Brain (NVIDIA Isaac)","docId":"module-isaac-sim/quiz","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/troubleshooting","label":"Troubleshooting Common NVIDIA Isaac Issues (Module 3)","docId":"module-isaac-sim/troubleshooting","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-isaac-sim/advanced-topics","label":"Optional Advanced Topics: NVIDIA Isaac and AI Robotics","docId":"module-isaac-sim/advanced-topics","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/Physical-AI-Humanoid-Robotics/docs/category/module-3-isaac-ai"},{"type":"category","label":"Module 4: Vision-Language-Action (VLA)","items":[{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-vla/introduction","label":"Introduction to Vision-Language-Action (VLA) Systems","docId":"module-vla/introduction","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-vla/labs","label":"VLA Lab: Basic Conversational Control","docId":"module-vla/labs","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-vla/code-examples","label":"Capstone Project: Autonomous Humanoid - Code Examples","docId":"module-vla/code-examples","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/module-vla/advanced-topics","label":"Optional Advanced Topics: Vision-Language-Action (VLA) Systems","docId":"module-vla/advanced-topics","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/Physical-AI-Humanoid-Robotics/docs/category/module-4-vla"},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/capstone-project","label":"Capstone Project: Autonomous Humanoid","docId":"capstone-project","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/glossary","label":"Glossary","docId":"glossary","unlisted":false},{"type":"link","href":"/Physical-AI-Humanoid-Robotics/docs/faq","label":"Frequently Asked Questions","docId":"faq","unlisted":false}]},"docs":{"capstone-project":{"id":"capstone-project","title":"Capstone Project: Autonomous Humanoid","description":"This Capstone Project brings together all the knowledge and skills you\'ve acquired throughout the textbook. Your goal is to develop a simulated autonomous humanoid robot capable of understanding high-level natural language commands, perceiving its environment, navigating to targets, identifying objects, and performing basic manipulation tasks.","sidebar":"tutorialSidebar"},"faq":{"id":"faq","title":"Frequently Asked Questions (FAQ)","description":"This section addresses common questions students and instructors might have about the \\"Physical AI & Humanoid Robotics Textbook\\" and its content.","sidebar":"tutorialSidebar"},"glossary":{"id":"glossary","title":"Glossary","description":"This glossary provides definitions for key terms and concepts used throughout the \\"Physical AI & Humanoid Robotics Textbook.\\" Understanding these terms is essential for comprehending the material.","sidebar":"tutorialSidebar"},"hardware-requirements":{"id":"hardware-requirements","title":"Hardware & Software Requirements","description":"This textbook is designed to be highly practical, with hands-on labs and simulations that require specific hardware and software configurations to ensure a smooth learning experience. Adhering to these recommendations will help you reproduce all experiments and exercises successfully.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Tutorial Intro","description":"Let\'s discover Docusaurus in less than 5 minutes."},"introduction":{"id":"introduction","title":"Introduction to Physical AI & Humanoid Robotics","description":"Welcome to the Physical AI & Humanoid Robotics Textbook! This book serves as a comprehensive guide for university students, engineers, and professionals looking to bridge the gap between theoretical AI concepts and their practical application in embodied robotic systems, specifically humanoid robots.","sidebar":"tutorialSidebar"},"module-digital-twin/advanced-topics":{"id":"module-digital-twin/advanced-topics","title":"Optional Advanced Topics: Digital Twin and Simulation","description":"This section explores more advanced topics related to digital twins and robotic simulation beyond the core material of Module 2. These topics are not essential for completing the main labs but offer deeper insights and practical applications for those interested in extending their simulation capabilities.","sidebar":"tutorialSidebar"},"module-digital-twin/code-examples":{"id":"module-digital-twin/code-examples","title":"Digital Twin Lab: Code Examples (Gazebo & Sensors)","description":"This section provides the complete code examples used in the \\"Importing URDF into Gazebo\\" and \\"Adding Sensors in Gazebo\\" labs for your convenience. You can download these files to ensure your setup is correct or to compare with your own implementations.","sidebar":"tutorialSidebar"},"module-digital-twin/introduction":{"id":"module-digital-twin/introduction","title":"Introduction to Digital Twins and Simulation","description":"The development of complex robotic systems, especially humanoids, presents unique challenges. Testing on physical hardware is often expensive, time-consuming, and potentially dangerous. This is where digital twins and simulation environments become indispensable tools. A digital twin is a virtual replica of a physical system, constantly updated with real-world data, enabling deep analysis and predictive maintenance. In robotics, a digital twin often manifests as a high-fidelity simulation.","sidebar":"tutorialSidebar"},"module-digital-twin/labs":{"id":"module-digital-twin/labs","title":"Digital Twin Lab: Importing URDF into Gazebo","description":"This lab will guide you through importing a URDF robot model, similar to the one you created in Module 1, into the Gazebo simulation environment. This is a crucial step in creating a digital twin of your robot, allowing you to test its physical properties and behaviors in a realistic virtual world.","sidebar":"tutorialSidebar"},"module-digital-twin/quiz":{"id":"module-digital-twin/quiz","title":"Module 2 Checkpoint Quiz: Digital Twin and Simulation","description":"This short quiz will test your understanding of digital twins, Gazebo, Unity, and sensor integration covered in Module 2. Choose the best answer for each question.","sidebar":"tutorialSidebar"},"module-digital-twin/sensor-lab":{"id":"module-digital-twin/sensor-lab","title":"Digital Twin Lab: Adding Sensors in Gazebo","description":"In the previous lab, you successfully imported your URDF robot into Gazebo. A robot\'s ability to perceive its environment is crucial for any autonomous behavior. This lab will guide you through adding a simulated sensor (specifically, a depth camera) to your robot model within Gazebo and visualizing its data in ROS 2.","sidebar":"tutorialSidebar"},"module-digital-twin/troubleshooting":{"id":"module-digital-twin/troubleshooting","title":"Troubleshooting Common Simulation Issues (Module 2)","description":"This section provides solutions to common problems you might encounter while working with Gazebo and simulated sensors in this module.","sidebar":"tutorialSidebar"},"module-isaac-sim/advanced-topics":{"id":"module-isaac-sim/advanced-topics","title":"Optional Advanced Topics: NVIDIA Isaac and AI Robotics","description":"This section delves into advanced capabilities and considerations for AI robotics using the NVIDIA Isaac platform, extending beyond the core VSLAM and Nav2 labs. These topics are ideal for students who wish to gain a deeper understanding of the underlying technologies and explore more sophisticated AI-driven robot behaviors.","sidebar":"tutorialSidebar"},"module-isaac-sim/bipedal-nav2-lab":{"id":"module-isaac-sim/bipedal-nav2-lab","title":"NVIDIA Isaac Lab: Bipedal Path Planning (Nav2)","description":"Once a robot can perceive and map its environment (VSLAM), the next crucial step is to enable it to navigate autonomously. For humanoid robots, this involves bipedal path planning, which is significantly more complex than planning for wheeled robots due to balance and gait considerations. This lab will guide you through using ROS 2\'s Navigation2 (Nav2) stack for path planning, adapted for a bipedal robot in Isaac Sim.","sidebar":"tutorialSidebar"},"module-isaac-sim/code-examples":{"id":"module-isaac-sim/code-examples","title":"NVIDIA Isaac Lab: Code Examples (VSLAM & Nav2)","description":"This section provides the complete code examples and configurations for the VSLAM and Nav2 labs in Module 3. You can use these files to verify your setup or as a reference for your own implementations.","sidebar":"tutorialSidebar"},"module-isaac-sim/introduction":{"id":"module-isaac-sim/introduction","title":"Introduction to AI-Robot Brain: NVIDIA Isaac","description":"In the previous module, you learned how to create digital twins and simulate robots. Now, we turn our attention to the \\"brain\\" of the robot \u2013 the AI that enables it to perceive, understand, and interact intelligently with its environment. NVIDIA Isaac provides a powerful platform for developing and deploying AI-powered robotics applications, leveraging NVIDIA\'s GPU capabilities for accelerated computing.","sidebar":"tutorialSidebar"},"module-isaac-sim/labs":{"id":"module-isaac-sim/labs","title":"NVIDIA Isaac Lab: Setting Up Isaac Sim with a Robot","description":"This lab will guide you through the process of setting up NVIDIA Isaac Sim and importing a robot model. Isaac Sim provides a highly realistic, physics-enabled simulation environment crucial for developing and testing AI-powered robotics applications.","sidebar":"tutorialSidebar"},"module-isaac-sim/quiz":{"id":"module-isaac-sim/quiz","title":"Module 3 Checkpoint Quiz: AI-Robot Brain (NVIDIA Isaac)","description":"This short quiz will test your understanding of AI perception, VSLAM, and navigation concepts using NVIDIA Isaac, as covered in Module 3. Choose the best answer for each question.","sidebar":"tutorialSidebar"},"module-isaac-sim/troubleshooting":{"id":"module-isaac-sim/troubleshooting","title":"Troubleshooting Common NVIDIA Isaac Issues (Module 3)","description":"This section provides solutions to common problems you might encounter while working with NVIDIA Isaac Sim, Isaac ROS, and Nav2 in this module. Given the complexity and resource demands of these tools, troubleshooting is a crucial skill.","sidebar":"tutorialSidebar"},"module-isaac-sim/vslam-lab":{"id":"module-isaac-sim/vslam-lab","title":"NVIDIA Isaac Lab: Visual SLAM (VSLAM)","description":"Visual Simultaneous Localization and Mapping (VSLAM) is a key AI robotics technology that allows a robot to build a map of an unknown environment while simultaneously estimating its own position within that map, using only visual sensor data (e.g., from a camera). This lab will guide you through running a VSLAM pipeline in Isaac Sim using Isaac ROS.","sidebar":"tutorialSidebar"},"module-ros2/advanced-topics":{"id":"module-ros2/advanced-topics","title":"Optional Advanced Topics: ROS 2","description":"This section delves into more advanced concepts and features of ROS 2 that are not essential for the core understanding of Module 1 but can significantly enhance your robotic development capabilities. These topics are suitable for students who wish to explore beyond the basics.","sidebar":"tutorialSidebar"},"module-ros2/introduction":{"id":"module-ros2/introduction","title":"Introduction to ROS 2","description":"The Robot Operating System (ROS) is a flexible framework for writing robot software. It\'s a collection of tools, libraries, and conventions that aim to simplify the task of creating complex and robust robot behaviors across a wide variety of robotic platforms. ROS 2 is the latest iteration, re-architected to address the limitations of ROS 1, particularly concerning real-time performance, multi-robot systems, and embedded platform support.","sidebar":"tutorialSidebar"},"module-ros2/labs":{"id":"module-ros2/labs","title":"ROS 2 Hands-on Lab: Publisher & Subscriber","description":"This lab will guide you through creating your first ROS 2 nodes: a simple Python publisher that sends \\"Hello ROS 2\\" messages and a Python subscriber that receives and prints them. This demonstrates the fundamental publish/subscribe communication pattern in ROS 2.","sidebar":"tutorialSidebar"},"module-ros2/quiz":{"id":"module-ros2/quiz","title":"Module 1 Checkpoint Quiz: ROS 2 Fundamentals","description":"This short quiz will test your understanding of the core concepts of ROS 2 covered in Module 1. Choose the best answer for each question.","sidebar":"tutorialSidebar"},"module-ros2/troubleshooting":{"id":"module-ros2/troubleshooting","title":"Troubleshooting Common ROS 2 Issues (Module 1)","description":"This section provides solutions to common problems you might encounter while working with ROS 2 in this module.","sidebar":"tutorialSidebar"},"module-ros2/urdf-fundamentals":{"id":"module-ros2/urdf-fundamentals","title":"Understanding URDF (Unified Robot Description Format)","description":"The Unified Robot Description Format (URDF) is an XML format for describing all elements of a robot. It\'s used in ROS 2 to represent the kinematic and dynamic properties of a robot, as well as its visual and collision characteristics. A URDF file allows ROS 2 tools and simulation environments (like Gazebo) to correctly interpret and display your robot model.","sidebar":"tutorialSidebar"},"module-vla/advanced-topics":{"id":"module-vla/advanced-topics","title":"Optional Advanced Topics: Vision-Language-Action (VLA) Systems","description":"This section explores advanced and emerging topics in Vision-Language-Action (VLA) systems for robotics, going beyond the basic conversational control demonstrated in the VLA lab. These topics are for those who wish to delve deeper into the research and cutting-edge developments in grounding language in robotics.","sidebar":"tutorialSidebar"},"module-vla/code-examples":{"id":"module-vla/code-examples","title":"Capstone Project: Autonomous Humanoid - Code Examples","description":"This section provides the complete code examples and configuration files for the Capstone Project and the VLA Lab. These are provided as a reference to help you integrate the various components of your autonomous humanoid.","sidebar":"tutorialSidebar"},"module-vla/introduction":{"id":"module-vla/introduction","title":"Introduction to Vision-Language-Action (VLA) Systems","description":"In the previous modules, you\'ve learned how robots perceive their environment (VSLAM), navigate autonomously (Nav2), and operate within physics-driven simulations. Now, we\'re ready to explore how to bridge the gap between human intent and robot execution through Vision-Language-Action (VLA) systems. VLA systems aim to enable robots to understand natural language instructions, interpret visual information, and translate this understanding into physical actions in the real (or simulated) world.","sidebar":"tutorialSidebar"},"module-vla/labs":{"id":"module-vla/labs","title":"VLA Lab: Basic Conversational Control","description":"This lab introduces the fundamentals of Vision-Language-Action (VLA) systems by guiding you through setting up a basic conversational interface for your simulated humanoid robot. You will integrate a Speech-to-Text (STT) service and a Large Language Model (LLM) to translate high-level natural language commands into simple robot actions.","sidebar":"tutorialSidebar"},"references":{"id":"references","title":"References and Bibliography","description":"This section provides a comprehensive list of all external sources cited throughout the \\"Physical AI & Humanoid Robotics Textbook.\\" All citations adhere to APA Style guidelines."},"setup-guide":{"id":"setup-guide","title":"Development Environment Setup Guide","description":"This guide provides comprehensive instructions for setting up your development environment for the Physical AI & Humanoid Robotics textbook. You will need a workstation running Ubuntu 22.04.","sidebar":"tutorialSidebar"},"tutorial-basics/congratulations":{"id":"tutorial-basics/congratulations","title":"Congratulations!","description":"You have just learned the basics of Docusaurus and made some changes to the initial template."},"tutorial-basics/create-a-blog-post":{"id":"tutorial-basics/create-a-blog-post","title":"Create a Blog Post","description":"Docusaurus creates a page for each blog post, but also a blog index page, a tag system, an RSS feed..."},"tutorial-basics/create-a-document":{"id":"tutorial-basics/create-a-document","title":"Create a Document","description":"Documents are groups of pages connected through:"},"tutorial-basics/create-a-page":{"id":"tutorial-basics/create-a-page","title":"Create a Page","description":"Add Markdown or React files to src/pages to create a standalone page:"},"tutorial-basics/deploy-your-site":{"id":"tutorial-basics/deploy-your-site","title":"Deploy your site","description":"Docusaurus is a static-site-generator (also called Jamstack)."},"tutorial-basics/markdown-features":{"id":"tutorial-basics/markdown-features","title":"Markdown Features","description":"Docusaurus supports Markdown and a few additional features."},"tutorial-extras/manage-docs-versions":{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs."},"tutorial-extras/translate-your-site":{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French."}}}}')}}]);